      Q('[data-fyj]', st).innerHTML = jar.length ? 'ağır kelimeler: ' + jar.slice(0, 6).map(function (w) { return '<mark>' + X(w) + '</mark>'; }).join(' ') + ' <em>daha basit söyleyebilir misin?</em>' : '';
